/// Why a step failed. Only `Product` (the library's outcome differs from the expectation) may count as pending; a
/// `Harness` failure (malformed scenario, unknown variable, runner or OS-oracle error) always fails the suite. Every
/// error not built as `Product` is `Harness`, so an unclassified failure fails closed.
#[derive(Debug)]
pub enum Fail {
    Product(String),
    Harness(String),
}

impl From<String> for Fail {
    fn from(msg: String) -> Fail {
        Fail::Harness(msg)
    }
}

impl From<&str> for Fail {
    fn from(msg: &str) -> Fail {
        Fail::Harness(msg.to_string())
    }
}

/// Checks `expect` against the outcome; `elapsedMs` is the step's own duration.
pub fn check(expect: &Value, got: &Outcome, elapsed: Duration) -> Result<(), Fail> {
    let want = expect.as_object().ok_or("`expect` must be an object")?;
    let product = |msg: String| Err(Fail::Product(msg));
    if let (Err(e), false) = (got, want.contains_key("error")) {
        return product(format!("unexpected error {e}"));
    }
    for (key, w) in want {
        match (key.as_str(), got) {
            ("elapsedMs", _) => {
                let ms = elapsed.as_secs_f64() * 1000.0;
                if !number(w, Some(ms))? {
                    return product(format!("elapsedMs: expected {w}, got {ms:.0}"));
                }
            }
            ("error", Ok(_)) => return product(format!("expected error {w}, got success")),
            ("error", Err(e)) => {
                let code = w.as_str().ok_or("`error` must be a code")?;
                if e.code().as_str() != code {
                    return product(format!("expected error {code}, got {e}"));
                }
            }
            ("message", Err(e)) => {
                let text = e.to_string();
                for part in w.as_array().map_or(vec![w], |a| a.iter().collect()) {
                    let part = part.as_str().ok_or("message parts must be strings")?;
                    if !text.contains(part) {
                        return product(format!("message {text:?} lacks {part:?}"));
                    }
                }
            }
            ("result", Err(e)) => match e.result() {
                Some(result) => fields(w, &run_fields(result)).map_err(|f| f.at("result"))?,
                None => return product(format!("error {e} carries no result")),
            },
            (_, Err(e)) => return product(format!("{key} expected, got error {e}")),
            (_, Ok(f)) => {
                let g = f
                    .get(key.as_str())
                    .ok_or_else(|| format!("{key}: not produced by this step"))?;
                field(w, g).map_err(|f| f.at(key))?;
            }
        }
    }
    Ok(())
}

fn fields(want: &Value, got: &Fields) -> Result<(), Fail> {
    for (key, w) in want.as_object().ok_or("want an object")? {
        let g = got.get(key.as_str()).ok_or_else(|| format!("{key}: no such field"))?;
        field(w, g).map_err(|f| f.at(key))?;
    }
    Ok(())
}

fn field(w: &Value, got: &Got) -> Result<(), Fail> {
    let (ok, shown) = match got {
        Got::Num(n) => (number(w, *n)?, n.map_or("null".into(), |n| n.to_string())),
        Got::Str(s) => (string(w, s.as_deref().map(|s| (s.as_bytes(), true)))?, format!("{s:?}")),
        Got::Bool(b) => (w.as_bool().ok_or("want true or false")? == *b, b.to_string()),
        Got::Data(Data::Text(t)) => (string(w, Some((t.as_bytes(), true)))?, shown(t.as_bytes())),
        Got::Data(Data::Bytes(b)) => (string(w, Some((b, false)))?, shown(b)),
        Got::Entries(list) => (entries(w, list)?, format!("{list:?}")),
        Got::Pieces(got) => {
            let want: Vec<(u64, bool)> = w
                .as_array()
                .ok_or("pieces: want a list")?
                .iter()
                .map(|p| {
                    (
                        p["bytes"].as_u64().unwrap_or(u64::MAX),
                        p["continues"].as_bool().unwrap_or(false),
                    )
                })
                .collect();
            (want == *got, format!("{got:?} (bytes, continues)"))
        }
        Got::Obj(f) => return fields(w, f),
    };
    if ok {
        Ok(())
    } else {
        Err(Fail::Product(format!("expected {w}, got {shown}")))
    }
}

/// Pids accepted by `pid`/`parentPid`: a number, a numeric string, or a list of them (a capture).
fn ids(v: &Value) -> Vec<f64> {
    match v {
        Value::Array(a) => a.iter().flat_map(ids).collect(),
        Value::String(s) => s.parse().into_iter().collect(),
        v => v.as_f64().into_iter().collect(),
    }
}

/// `entries`: an unordered list matched one to one.
fn entries(w: &Value, got: &[ProcessInfo]) -> Result<bool, String> {
    let want = w.as_array().ok_or("entries must be a list")?;
    let mut ok = vec![vec![false; got.len()]; want.len()];
    for (i, e) in want.iter().enumerate() {
        for (j, p) in got.iter().enumerate() {
            ok[i][j] = entry(e, p)?;
        }
    }
    Ok(want.len() == got.len() && assign(&ok, 0, &mut vec![false; got.len()]))
}

fn assign(ok: &[Vec<bool>], i: usize, used: &mut [bool]) -> bool {
    let Some(row) = ok.get(i) else { return true };
    for j in 0..row.len() {
        if row[j] && !used[j] {
            used[j] = true;
            if assign(ok, i + 1, used) {
                return true;
            }
            used[j] = false;
        }
    }
    false
}

fn entry(e: &Value, p: &ProcessInfo) -> Result<bool, String> {
    let mut ok = true;
    for (key, w) in e.as_object().ok_or("an entry must be an object")? {
        ok &= match key.as_str() {
            "pid" => ids(w).contains(&f64::from(p.pid)),
            "parentPid" if w.is_null() => p.parent_pid.is_none(),
            "parentPid" => p.parent_pid.is_some_and(|pp| ids(w).contains(&f64::from(pp))),
            "name" => string(w, p.name.as_deref().map(|n| (n.as_bytes(), true)))?,
            _ => return Err(format!("unknown entry key {key}")),
        };
    }
    Ok(ok)
}

/// Checks step `s`, whose action is `name` with value `target`.
pub fn step(name: &str, target: &Value, s: &Map<String, Value>) -> Check {
    match name {
        "run" | "spawn" => match target.as_array() {
            Some(argv) if !argv.is_empty() && argv.iter().all(Value::is_string) => Ok(()),
            _ => Err(format!("`{name}` takes [command, ...args] as strings")),
        },
        "os" => one_of(target, &["alive", "dead"]),
        _ => text(target),
    }?;
    for (key, v) in s.iter().filter(|(k, _)| *k != name) {
        match key.as_str() {
            "timeoutMs" | "withinMs" | "graceMs" | "cols" | "rows" => count(v),
            "as" => text(v),
            "capture" if name == "processes" => text(v),
            "capture" => object(v)?.values().try_for_each(regex),
            "await" | "close" | "detach" | "lines" => boolean(v),
            "data" => data(v),
            "until" => until(v),
            "pids" => match v {
                Value::Array(a) if !a.is_empty() && a.iter().all(|p| p.is_string() || p.is_u64()) => Ok(()),
                Value::String(_) => Ok(()),
                _ => Err("want a capture or a non-empty list of pids".into()),
            },
            "options" => options(v),
            "expect" => expect(name, s, v),
            _ => Err("unknown key".into()),
        }
        .map_err(|e| format!("{key}: {e}"))?;
    }
    Ok(())
}

fn expect(name: &str, s: &Map<String, Value>, v: &Value) -> Check {
    let want = object(v)?;
    let lines = s.get("lines") == Some(&Value::Bool(true));
    for (key, w) in want {
        let allowed = match (name, key.as_str()) {
            (_, "error" | "elapsedMs") => true,
            (_, "message" | "result") => want.contains_key("error"),
            ("run" | "wait", k) => EXIT.contains(&k) || k == "stdout" || k == "stderr",
            ("stop", k) => EXIT.contains(&k),
            ("read", "pieces") => lines,
            ("read", k) => STREAMS.contains(&k) || ["chunks", "lostBefore", "continues", "droppedBytes"].contains(&k),
            ("processes", "entries") => true,
            _ => false,
        };
        if !allowed {
            return Err(format!("`{name}` cannot expect `{key}` (here)"));
        }
        match key.as_str() {
            "error" => one_of(w, &CODES),
            "message" => match w {
                Value::String(_) => Ok(()),
                Value::Array(a) if !a.is_empty() && a.iter().all(Value::is_string) => Ok(()),
                _ => Err("want text or a list of texts".into()),
            },
            "result" => object(w)?.iter().try_for_each(|(k, m)| result_field(k, m)),
            "droppedBytes" => object(w)?.iter().try_for_each(|(k, m)| match k.as_str() {
                "stdout" | "stderr" => number(m),
                _ => Err(format!("unknown stream {k}")),
            }),
            "pieces" => object(w)?.iter().try_for_each(|(k, list)| pieces(k, list)),
            "entries" => w.as_array().ok_or("want a list")?.iter().try_for_each(entry),
            k if STREAMS.contains(&k) => string(w),
            k => result_field(k, w),
        }
        .map_err(|e| format!("{key}: {e}"))?;
    }
    Ok(())
}

/// A field of an `Exit` or `RunResult` (or a numeric field of `read`).
fn result_field(key: &str, w: &Value) -> Check {
    match key {
        "exitCode" | "chunks" | "lostBefore" | "continues" | "elapsedMs" => number(w),
        "signal" => string(w),
        "reason" => one_of(w, &REASONS),
        "success" => boolean(w),
        "stdout" | "stderr" => string(w),
        _ => Err(format!("unknown field {key}")),
    }
}

fn pieces(stream: &str, list: &Value) -> Check {
    if !STREAMS.contains(&stream) {
        return Err(format!("unknown stream {stream}"));
    }
    for piece in list.as_array().ok_or("want a list of pieces")? {
        let p = object(piece)?;
        if p.len() != 2
            || !p.get("bytes").is_some_and(Value::is_u64)
            || !p.get("continues").is_some_and(Value::is_boolean)
        {
            return Err(format!("a piece is {{\"bytes\": n, \"continues\": bool}}, not {piece}"));
        }
    }
    Ok(())
}

fn entry(e: &Value) -> Check {
    for (k, w) in object(e)? {
        let ids = |w: &Value| match w {
            Value::String(_) => true,
            Value::Array(a) => a.iter().all(|x| x.is_string() || x.is_u64()),
            w => w.is_u64(),
        };
        match k.as_str() {
            "pid" if ids(w) => {}
            "parentPid" if w.is_null() || ids(w) => {}
            "name" => string(w)?,
            _ => return Err(format!("bad entry key {k}: {w}")),
        }
    }
    Ok(())
}

/// Checks step `s` (action `name`, value `target`) against the earlier steps, then records what it defines.
pub fn step(&mut self, name: &str, target: &Value, s: &Map<String, Value>) -> Check {
    schema::step(name, target, s)?;
    let has = |k: &str| s.contains_key(k);
    let flag = |k: &str| s.get(k).and_then(Value::as_bool);
    let kind = target.as_str().and_then(|h| self.handles.get(h).copied());
    let child = matches!(kind, Some(Kind::Pipe | Kind::Pty));
    let required: Result<(), &str> = match name {
        "run" if has("as") != (flag("await") == Some(false)) => {
            Err("`as` goes with `await: false`, and only with it")
        }
        "write" if !child => Err("needs an earlier spawned child"),
        // SPEC: `write` without `data` only closes stdin.
        "write" if !has("data") && flag("close") == Some(false) => Err("without `data` it closes stdin"),
        "write" if flag("close").unwrap_or(!has("data")) && kind == Some(Kind::Pty) => {
            Err("closes stdin, which a terminal does not have")
        }
        "read" | "stop" | "processes" if !child => Err("needs an earlier spawned child"),
        "read" if !has("until") => Err("needs `until`"),
        "wait" if kind.is_none() => Err("needs an earlier spawned child or `run` with `await: false`"),
        "resize" if kind != Some(Kind::Pty) => Err("needs an earlier spawned terminal child (`pty`)"),
        "resize" if !has("cols") || !has("rows") => Err("needs `cols` and `rows`"),
        "resize"
            if ["cols", "rows"]
                .iter()
                .any(|k| s[*k].as_u64().is_some_and(|n| n > u64::from(u16::MAX))) =>
        {
            Err("`cols` and `rows` must fit 16 bits")
        }
        "os" if !has("pids") => Err("needs `pids`"),
        _ => Ok(()),
    };
    required.map_err(|e| format!("`{name}` {e}"))?;
    for (key, v) in s.iter().filter(|(k, _)| *k != "expect") {
        self.vars_in(v).map_err(|e| format!("{key}: {e}"))?;
    }
    self.define(name, s);
    match s.get("expect") {
        Some(want) => self.vars_in(want).map_err(|e| format!("expect: {e}")),
        None => Ok(()),
    }
}

/// Parses and validates a scenario; `stem` is its file name without `.json`, which must equal the id.
pub fn load(text: &str, stem: &str) -> Result<Scenario, String> {
    let json: Map<String, Value> = serde_json::from_str(text).map_err(|e| format!("bad JSON: {e}"))?;
    if let Some(key) = json
        .keys()
        .find(|k| !["id", "os", "langs", "files", "steps"].contains(&k.as_str()))
    {
        return Err(format!("unknown key {key}"));
    }
    let id = json.get("id").and_then(Value::as_str).ok_or("missing id")?;
    if id != stem || !pattern(r"^C-[A-Z]+-\d\d\.[a-z0-9-]+$")?.is_match(id) {
        return Err(format!("id {id:?} must be `<item>.<name>` and equal the file name"));
    }
    for (key, allowed) in [("os", &OSES), ("langs", &LANGS)] {
        if let Some(v) = json.get(key) {
            let list = v.as_array().ok_or_else(|| format!("{key} must be a list"))?;
            if list.is_empty() || !list.iter().all(|x| x.as_str().is_some_and(|x| allowed.contains(&x))) {
                return Err(format!("{key} must list some of {allowed:?}"));
            }
        }
    }
    let mut names = Names::new();
    names.files(json.get("files"))?;
    let steps = json
        .get("steps")
        .and_then(Value::as_array)
        .filter(|s| !s.is_empty())
        .ok_or("missing steps")?;
    for (i, step) in steps.iter().enumerate() {
        let (name, target) = action(step).map_err(|e| format!("step {i}: {e}"))?;
        let obj = step.as_object().ok_or_else(|| format!("step {i}: not an object"))?;
        names
            .step(name, target, obj)
            .map_err(|e| format!("step {i} ({name}): {e}"))?;
    }
    Ok(Scenario { json })
}

